import com.example.actvremotefreeware.model.FanSpeed

/**
 * Ported and enhanced from IR-AC-Remote-master.
 * Sequence 1: Samsung & Whirlpool
 * Sequence 2: Daikin & LG
 * Sequence 3: Voltas & Panasonic
 * Converts pulse count multiples (count * 1000000 / frequency) into microsecond timings.
 */
object SequenceAcProtocols {

    fun encode(state: AcState, sequenceIndex: Int): Pair<Int, IntArray> {
        val frequency = when (sequenceIndex) {
            1 -> 38028
            2 -> 38461
            else -> 38000
        }

        val rawTimingString = if (!state.power) {
            getSequenceCode(sequenceIndex, KEY_POWER_OFF) ?: getSequenceCode(sequenceIndex, KEY_POWER_ON)
        } else {
            // Pick code for current temperature or mode
            getSequenceCode(sequenceIndex, state.temp)
                ?: getSequenceCode(sequenceIndex, getModeKey(state.mode))
                ?: getSequenceCode(sequenceIndex, KEY_POWER_ON)
        } ?: ""

        val pattern = parseToMicroseconds(rawTimingString, frequency)
        return Pair(frequency, pattern)
    }

    private const val KEY_POWER_ON = 0
    private const val KEY_POWER_OFF = 1
    private const val KEY_SWING_ON = 100
    private const val KEY_SWING_OFF = 101
    private const val KEY_FAN_AUTO = 200
    private const val KEY_FAN_LOW = 201
    private const val KEY_FAN_MED = 202
    private const val KEY_FAN_HIGH = 203
    private const val KEY_MODE_AUTO = 250
    private const val KEY_MODE_COOL = 251
    private const val KEY_MODE_DRY = 252
    private const val KEY_MODE_FAN = 253
    private const val KEY_MODE_HEAT = 254

    private fun getModeKey(mode: AcMode): Int = when (mode) {
        AcMode.AUTO -> KEY_MODE_AUTO
        AcMode.COOL -> KEY_MODE_COOL
        AcMode.DRY -> KEY_MODE_DRY
        AcMode.FAN -> KEY_MODE_FAN
        AcMode.HEAT -> KEY_MODE_HEAT
    }

    fun parseToMicroseconds(csvPulses: String, frequency: Int): IntArray {
        if (csvPulses.isBlank()) return intArrayOf()
        val pulseMultiplier = 1000000 / frequency
        val tokens = csvPulses.split(",")
        val result = IntArray(tokens.size)
        for (i in tokens.indices) {
            val token = tokens[i].trim()
            result[i] = (token.toIntOrNull() ?: 0) * pulseMultiplier
        }
        return result
    }

    private fun getSequenceCode(seq: Int, key: Int): String? {
        return when (seq) {
            1 -> SEQ1_MAP[key] ?: SEQ1_MAP[KEY_POWER_ON]
            2 -> SEQ2_MAP[key] ?: SEQ2_MAP[KEY_POWER_ON]
            3 -> SEQ3_MAP[key] ?: SEQ3_MAP[KEY_POWER_ON]
            else -> SEQ1_MAP[key]
        }
    }

